        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        String[] patient = new String[n], doctor = new String[n], drug = new String[n];
        long[] date = new long[n];
        for (int i = 0; i < n; i++) {
            patient[i] = st.nextToken();
            doctor[i] = st.nextToken();
            drug[i] = st.nextToken();
            date[i] = Long.parseLong(st.nextToken());
        }
        List<String[]> res = findPairs(patient, doctor, drug, date);
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append("\n");
        for (String[] pr : res) sb.append(pr[0]).append(" ").append(pr[1]).append("\n");
